from collections import deque

def solve():
    n = 3
    # Board is represented as a tuple of n*n bits
    initial_board = (0,) * (n * n)

    # L-trominoes: (x,y), (x+1,y), (x,y+1)
    trominoes = []
    for x in range(n - 1):
        for y in range(n - 1):
            trominoes.append(((x, y), (x + 1, y), (x, y + 1)))

    queue = deque([(initial_board, [])])
    visited = {initial_board}

    while queue:
        board, path = queue.popleft()

        if len(path) > 0 and board == initial_board:
            return path

        # Move 1: Place a tromino
        for tromino in trominoes:
            cells = []
            possible = True
            for (x, y) in tromino:
                idx = x * n + y
                if board[idx] == 1:
                    possible = False
                    break
                cells.append(idx)

            if possible:
                new_board = list(board)
                for idx in cells:
                    new_board[idx] = 1
                new_board = tuple(new_board)
                if new_board not in visited:
                    visited.add(new_board)
                    queue.append((new_board, path + ["place"]))

        # Move 2: Remove a column
        for j in range(n):
            all_full = True
            for i in range(n):
                if board[i * n + j] == 0:
                    all_full = False
                    break
            if all_full:
                new_board = list(board)
                for i in range(n):
                    new_board[i * n + j] = 0
                new_board = tuple(new_board)
                if new_board not in visited:
                    visited.add(new_board)
                    queue.append((new_board, path + ["remove_col"]))

        # Move 3: Remove a row
        for i in range(n):
            all_full = True
            for j in range(n):
                if board[i * n + j] == 0:
                    all_full = False
                    break
            if all_full:
                new_board = list(board)
                for j in range(n):
                    new_board[i * n + j] = 0
                new_board = tuple(new_board)
                if new_board not in visited:
                    visited.add(new_board)
                    queue.append((new_board, path + ["remove_row"]))

    return None

